// 国別ガイドの、エリア分け（一覧でエリアごとにまとめる）。新しい国は ids に足す
export const COUNTRY_AREAS = [
  ["asia", "アジア", ["country-thailand", "country-korea", "country-taiwan", "country-vietnam", "country-singapore", "country-malaysia", "country-philippines", "country-indonesia", "country-hongkong", "country-cambodia", "country-mongolia", "country-turkey", "country-china", "country-india"]],
  ["europe", "ヨーロッパ", ["country-uk", "country-france", "country-italy", "country-spain", "country-germany"]],
  ["africa", "アフリカ", ["country-egypt", "country-morocco", "country-kenya"]],
  ["namerica", "北米", ["country-usa", "country-canada", "country-mexico"]],
  ["samerica", "南米", ["country-peru", "country-bolivia", "country-brazil", "country-argentina", "country-chile"]],
  ["oceania", "オセアニア", ["country-australia", "country-newzealand"]],
];
// 記事のエリア（d.area があればそれを優先）。どこにも入っていなければ "other"
export const areaOf = (d) => d.area || (COUNTRY_AREAS.find((a) => a[2].includes(d.id)) || ["other"])[0];

export const BOARD_CATS = [["prep", "準備"], ["flight", "航空券"], ["save", "節約"], ["money", "お金・通信"], ["country", "国別ガイド"], ["geo", "旅と地理"], ["trouble", "事件簿"]];

