    facts: [["調べる場所", "外務省・行き先の国の大使館"], ["調べる時期", "航空券を取る前"], ["よく出てくる制度", "ESTA（アメリカ）・ETA（イギリス）など"]],
    blocks: [
      { t: "p", x: "観光での短い旅行なら、日本のパスポートでビザなしで入れる国はたくさんあります。ただ、「ビザはいらないけど、事前にネットで申請が必要」という国も増えています。申請を忘れると、飛行機に乗れないこともあるので、航空券を取る前に一度確認しておきましょう。" },
      { t: "h", x: "調べ方" },
      { t: "steps", items: [
        ["外務省のページを見る", "外務省の「海外安全ホームページ」には、国ごとの入国の条件がまとまっています。まずはここで、ビザが必要かどうかと、滞在できる日数を確認します。"],
        ["行き先の国の大使館のページを見る", "条件はときどき変わります。いちばん新しい情報は、行き先の国の大使館や政府のページに載っています。"],
        ["乗り継ぐ国も確認する", "乗り継ぎで空港の外に出る場合や、国によっては乗り継ぎだけでも手続きが必要なことがあります。経由する国の条件も見ておきましょう。"],
      ] },
      { t: "h", x: "よく出てくる電子渡航認証" },
      { t: "list", items: ["アメリカ：ESTA（エスタ）", "カナダ：eTA", "イギリス：ETA", "オーストラリア：ETA（専用のアプリから申請）", "ヨーロッパ（シェンゲン協定の国など）：ETIAS（エティアス）。2026年の終わりごろから始まる予定です。始まっているかどうかは、EUの公式サイトで確認してください"] },
      { t: "h", x: "ビザ以外にも見ておくこと" },
      { t: "list", items: ["パスポートの残りの有効期間（6か月以上必要な国が多いです）", "パスポートの空白のページ（スタンプを押すページが残っているか）", "帰りの航空券（入国のときに見せるよう言われることがあります）"] },
      { t: "note", x: "電子渡航認証には、公式サイトにそっくりな「申請代行サイト」がたくさんあります。高い手数料を取られることがあるので、申請は必ず公式サイトからしてください。" },
    ],
