    id: "student-budget", cat: "save", ill: "wallet", order: 11, mins: 7, updated: "2026-11-24",
    title: "学生が海外旅行を安くする方法",
    lead: "お金がなくても、海外には行けます。旅の費用を大きく下げるコツを、航空券・宿・移動・食事・学割の順にまとめました。",
